@@ -1,0 +1,123 @@
+@namespace sv_74a3bd47b7bb4ed5bf3868c97852f778.Components.Pages.Apply
+
+<h4 class="mb-3">References</h4>
+
+@for (int i = 0; i < References.Count; i++)
+{
+    var index = i;
+    var r = References[index];
+
+    <div class="card mb-3">
+        <div class="card-body">
+            <div class="d-flex justify-content-between align-items-center mb-2">
+                <h6 class="mb-0">Reference @(index + 1)</h6>
+                @if (References.Count > 1)
+                {
+                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
+                }
+            </div>
+
+            <div class="row mb-2">
+                <div class="col-md-6">
+                    <label class="form-label">Name <span class="text-danger">*</span></label>
+                    <input class="form-control" value="@r.Name"
+                           @onchange="e => UpdateRef(index, r with { Name = e.Value?.ToString() ?? "" })" />
+                </div>
+                <div class="col-md-6">
+                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
+                    <input class="form-control" value="@r.Relationship"
+                           @onchange="e => UpdateRef(index, r with { Relationship = e.Value?.ToString() ?? "" })" />
+                </div>
+            </div>
+
+            <div class="row mb-2">
+                <div class="col-md-6">
+                    <label class="form-label">Email <span class="text-danger">*</span></label>
+                    <input type="email" class="form-control" value="@r.Email"
+                           @onchange="e => UpdateRef(index, r with { Email = e.Value?.ToString() ?? "" })" />
+                </div>
+                <div class="col-md-6">
+                    <label class="form-label">Phone <span class="text-danger">*</span></label>
+                    <input type="tel" class="form-control" value="@r.Phone"
+                           @onchange="e => UpdateRef(index, r with { Phone = e.Value?.ToString() ?? "" })" />
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@if (References.Count < 3)
+{
+    <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddReference">
+        &#43; Add Reference
+    </button>
+}
+
+@if (ValidationError is not null)
+{
+    <div class="alert alert-danger">@ValidationError</div>
+}
+
+<div class="d-flex justify-content-between">
+    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
+    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
+</div>
+
+@code {
+    [Parameter] public List<ReferenceModel> References { get; set; } = [];
+    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
+    [Parameter] public EventCallback OnNext { get; set; }
+    [Parameter] public EventCallback OnBack { get; set; }
+
+    private string? ValidationError;
+
+    public record ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+
+    private void UpdateRef(int index, ReferenceModel updated)
+    {
+        References[index] = updated;
+        ReferencesChanged.InvokeAsync(References);
+    }
+
+    private void AddReference()
+    {
+        if (References.Count < 3)
+        {
+            References.Add(new ReferenceModel());
+            ReferencesChanged.InvokeAsync(References);
+        }
+    }
+
+    private void RemoveReference(int index)
+    {
+        References.RemoveAt(index);
+        ReferencesChanged.InvokeAsync(References);
+    }
+
+    private async Task HandleNext()
+    {
+        ValidationError = null;
+        if (References.Count < 2)
+        {
+            ValidationError = "Please provide at least 2 references.";
+            return;
+        }
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                ValidationError = "All fields are required for each reference.";
+                return;
+            }
+        }
+        await OnNext.InvokeAsync();
+    }
+}
+

