@using sv_74a3bd47b7bb4ed5bf3868c97852f778.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                @bind-FullName="fullName"
                @bind-Email="email"
                @bind-Phone="phone"
                @bind-Address="address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="NextStep" />
            break;

        case 1:
            <WorkHistoryStep
                @bind-Entries="workEntries"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 2:
            <ReferencesStep
                @bind-References="references"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 3:
            <CoverLetterStep
                @bind-CoverLetter="coverLetter"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 4:
            <ReviewStep
                FullName="@fullName"
                Email="@email"
                Phone="@phone"
                Address="@address"
                WorkEntries="@workEntries"
                References="@references"
                CoverLetter="@coverLetter"
                OnEditStep="GoToStep"
                OnBack="PreviousStep"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;

    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private List<WorkHistoryStep.WorkEntryModel> workEntries = [new()];
    private List<ReferencesStep.ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(fullName, email, phone, address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.step-indicator {
    counter-reset: step;
    padding: 0;
    position: relative;
}

.step-item {
    position: relative;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    font-weight: bold;
    font-size: 0.9rem;
}

.step-label {
    font-size: 0.8rem;
}

.step-item + .step-item::before {
    content: "";
    position: absolute;
    top: 18px;
    right: 50%;
    width: 100%;
    height: 2px;
    background-color: #dee2e6;
    z-index: -1;
}

.step-item.completed + .step-item::before {
    background-color: #198754;
}

