1. @namespace sv_74a3bd47b7bb4ed5bf3868c97852f778.Components.Pages.ApplySteps
2. 
3. <h4 class="mb-3">Work History</h4>
4. 
5. @for (int i = 0; i < Entries.Count; i++)
6. {
7.     var index = i;
8.     var entry = Entries[index];
9. 
10.     <div class="card mb-3">
11.         <div class="card-body">
12.             <div class="d-flex justify-content-between align-items-center mb-2">
13.                 <h6 class="mb-0">Position @(index + 1)</h6>
14.                 @if (Entries.Count > 1)
15.                 {
16.                     <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
17.                 }
18.             </div>
19. 
20.             <div class="row mb-2">
21.                 <div class="col-md-6">
22.                     <label class="form-label">Company Name <span class="text-danger">*</span></label>
23.                     <input class="form-control" value="@entry.Company"
24.                            @onchange="e => UpdateEntry(index, entry with { Company = e.Value?.ToString() ?? "" })" />
25.                 </div>
26.                 <div class="col-md-6">
27.                     <label class="form-label">Job Title <span class="text-danger">*</span></label>
28.                     <input class="form-control" value="@entry.Title"
29.                            @onchange="e => UpdateEntry(index, entry with { Title = e.Value?.ToString() ?? "" })" />
30.                 </div>
31.             </div>
32. 
33.             <div class="row mb-2">
34.                 <div class="col-md-4">
35.                     <label class="form-label">Start Date <span class="text-danger">*</span></label>
36.                     <input type="date" class="form-control" value="@entry.StartDate.ToString("yyyy-MM-dd")"
37.                            @onchange="e => UpdateEntry(index, entry with { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : entry.StartDate })" />
38.                 </div>
39.                 <div class="col-md-4">
40.                     <label class="form-label">End Date</label>
41.                     <input type="date" class="form-control" value="@entry.EndDate?.ToString("yyyy-MM-dd")"
42.                            disabled="@entry.IsCurrent"
43.                            @onchange="e => UpdateEntry(index, entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null })" />
44.                 </div>
45.                 <div class="col-md-4 d-flex align-items-end mb-1">
46.                     <div class="form-check">
47.                         <input class="form-check-input" type="checkbox" id="current-@index" checked="@entry.IsCurrent"
48.                                @onchange="e => UpdateEntry(index, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
49.                         <label class="form-check-label" for="current-@index">Currently working here</label>
50.                     </div>
51.                 </div>
52.             </div>
53. 
54.             <div class="mb-2">
55.                 <label class="form-label">Description</label>
56.                 <textarea class="form-control" rows="2" value="@entry.Description"
57.                           @onchange="e => UpdateEntry(index, entry with { Description = e.Value?.ToString() ?? "" })"></textarea>
58.             </div>
59.         </div>
60.     </div>
61. }
62. 
63. <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddEntry">
64.     &#43; Add Another Position
65. </button>
66. 
67. @if (ValidationError is not null)
68. {
69.     <div class="alert alert-danger">@ValidationError</div>
70. }
71. 
72. <div class="d-flex justify-content-between">
73.     <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
74.     <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
75. </div>
76. 
77. @code {
78.     [Parameter] public List<WorkEntryModel> Entries { get; set; } = [];
79.     [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
80.     [Parameter] public EventCallback OnNext { get; set; }
81.     [Parameter] public EventCallback OnBack { get; set; }
82. 
83.     private string? ValidationError;
84. 
85.     public class WorkEntryModel
86.     {
87.         public string Company { get; set; } = "";
88.         public string Title { get; set; } = "";
89.         public DateTime StartDate { get; set; } = DateTime.Today;
90.         public DateTime? EndDate { get; set; }
91.         public bool IsCurrent { get; set; }
92.         public string Description { get; set; } = "";
93.     }
94. 
95.     private void UpdateEntry(int index, WorkEntryModel updated)
96.     {
97.         Entries[index] = updated;
98.         EntriesChanged.InvokeAsync(Entries);
99.     }
100. 
101.     private void AddEntry()
102.     {
103.         Entries.Add(new WorkEntryModel());
104.         EntriesChanged.InvokeAsync(Entries);
105.     }
106. 
107.     private void RemoveEntry(int index)
108.     {
109.         Entries.RemoveAt(index);
110.         EntriesChanged.InvokeAsync(Entries);
111.     }
112. 
113.     private async Task HandleNext()
114.     {
115.         ValidationError = null;
116.         foreach (var entry in Entries)
117.         {
118.             if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
119.             {
120.                 ValidationError = "Company name and job title are required for each position.";
121.                 return;
122.             }
123.         }
124.         await OnNext.InvokeAsync();
125.     }
126. }
127.

